icipation"],"correctAnswer":"constitutional rights","explanation":"«constitutional rights» — «конституционные права»."},{"id":6,"question":"Выбери точное русское значение выражения «parliamentary committee».","options":["парламентский комитет","законодательное предложение","медиаграмотность","независимый надзор"],"correctAnswer":"парламентский комитет","explanation":"«parliamentary committee» — «парламентский комитет»."},{"id":7,"question":"Выбери точное русское значение выражения «institutional transparency».","options":["конституционные права","независимый надзор","прозрачность институтов","законодательное предложение"],"correctAnswer":"прозрачность институтов","explanation":"«institutional transparency» — «прозрачность институтов»."},{"id":8,"question":"Какое выражение на британском английском соответствует «политика на основе фактических данных»?","options":["institutional transparency","independent oversight","evidence-based policy","minority representation"],"correctAnswer":"evidence-based policy","explanation":"«evidence-based policy» — «политика на основе фактических данных»."}],"durationMinutes":8}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000205,'quizzes','{"id":760200000000205,"title":"C1 · Политика · Общество и правила · Quiz 5","description":"C1: общество и правила. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"📝","xp":40,"category":"Общество и правила","track":"Политика","topic":"Общество и правила","duration":"9 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «policy evaluation».","options":["процедурная справедливость","делиберативная демократия","конфликт интересов","оценка государственной политики"],"correctAnswer":"оценка государственной политики","explanation":"«policy evaluation» — «оценка государственной политики»."},{"id":2,"question":"Какое выражение на британском английском соответствует «гражданская вовлечённость»?","options":["evidence-based deliberation","constitutional interpretation","civic engagement","conflict of interest"],"correctAnswer":"civic engagement","explanation":"«civic engagement» — «гражданская вовлечённость»."},{"id":3,"question":"Выбери точное русское значение выражения «evidence-based deliberation».","options":["гражданская вовлечённость","независимость судебной власти","обсуждение на основе фактических данных","демократическая легитимность"],"correctAnswer":"обсуждение на основе фактических данных","explanation":"«evidence-based deliberation» — «обсуждение на основе фактических данных»."},{"id":4,"question":"Выбери точное русское значение выражения «procedural fairness».","options":["делиберативная демократия","обсуждение на основе фактических данных","гражданская вовлечённость","процедурная справедливость"],"correctAnswer":"процедурная справедливость","explanation":"«procedural fairness» — «процедурная справедливость»."},{"id":5,"question":"Какое выражение на британском английском соответствует «парламентский контроль»?","options":["parliamentary scrutiny","conflict of interest","judicial independence","policy evaluation"],"correctAnswer":"parliamentary scrutiny","explanation":"«parliamentary scrutiny» — «парламентский контроль»."},{"id":6,"question":"Выбери точное русское значение выражения «institutional safeguards».","options":["процедурная справедливость","институциональные гарантии","обсуждение на основе фактических данных","конфликт интересов"],"correctAnswer":"институциональные гарантии","explanation":"«institutional safeguards» — «институциональные гарантии»."},{"id":7,"question":"Выбери точное русское значение выражения «judicial independence».","options":["независимость судебной власти","толкование конституции","делиберативная демократия","парламентский контроль"],"correctAnswer":"независимость судебной власти","explanation":"«judicial independence» — «независимость судебной власти»."},{"id":8,"question":"Какое выражение на британском английском соответствует «подотчётность государственного сектора»?","options":["judicial independence","civic engagement","procedural fairness","public-sector accountability"],"correctAnswer":"public-sector accountability","explanation":"«public-sector accountability» — «подотчётность государственного сектора»."}],"durationMinutes":9}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000206,'quizzes','{"id":760200000000206,"title":"C2 · Политика · Общество и правила · Quiz 6","description":"C2: общество и правила. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"📝","xp":48,"category":"Общество и правила","track":"Политика","topic":"Общество и правила","duration":"10 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «articulate a proportionality test».","options":["отличить корреляцию от причинности","сбалансировать прозрачность и конфиденциальность","сформулировать проверку соразмерности","оценить легитимность института"],"correctAnswer":"сформулировать проверку соразмерности","explanation":"«articulate a proportionality test» — «сформулировать проверку соразмерности»."},{"id":2,"question":"Какое выражение на британском английском соответствует «оспорить неподкреплённое утверждение»?","options":["challenge an unsubstantiated claim","evaluate institutional legitimacy","analyse regulatory capture","reconcile competing public interests"],"correctAnswer":"challenge an unsubstantiated claim","explanation":"«challenge an unsubstantiated claim» — «оспорить неподкреплённое утверждение»."},{"id":3,"question":"Выбери точное русское значение выражения «examine procedural safeguards».","options":["изучить процессуальные гарантии","отличить корреляцию от причинности","сбалансировать прозрачность и конфиденциальность","согласовать конкурирующие общественные интересы"],"correctAnswer":"изучить процессуальные гарантии","explanation":"«examine procedural safeguards» — «изучить процессуальные гарантии»."},{"id":4,"question":"Выбери точное русское значение выражения «scrutinise constitutional constraints».","options":["оценить устойчивость демократии","оспорить неподкреплённое утверждение","согласовать конкурирующие общественные интересы","тщательно изучить конституционные ограничения"],"correctAnswer":"тщательно изучить конституционные ограничения","explanation":"«scrutinise constitutional constraints» — «тщательно изучить конституционные ограничения»."},{"id":5,"question":"Какое выражение на британском английском соответствует «обеспечить беспристрастность суда»?","options":["balance transparency and privacy","distinguish correlation from causation","assess democratic resilience","safeguard judicial impartiality"],"correctAnswer":"safeguard judicial impartiality","explanation":"«safeguard judicial impartiality» — «обеспечить беспристрастность суда»."},{"id":6,"question":"Выбери точное русское значение выражения «reconcile competing public interests».","options":["согласовать конкурирующие общественные интересы","тщательно изучить конституционные ограничения","отличить корреляцию от причинности","сбалансировать прозрачность и конфиденциальность"],"correctAnswer":"согласовать конкурирующие общественные интересы","explanation":"«reconcile competing public interests» — «согласовать конкурирующие общественные интересы»."},{"id":7,"question":"Выбери точное русское значение выражения «analyse regulatory capture».","options":["проанализировать захват регулятора","обеспечить беспристрастность суда","оценить легитимность института","избегать партийно-пристрастной подачи"],"correctAnswer":"проанализировать захват регулятора","explanation":"«analyse regulatory capture» — «проанализировать захват регулятора»."},{"id":8,"question":"Какое выражение на британском английском соответствует «избегать партийно-пристрастной подачи»?","options":["avoid partisan framing","challenge an unsubstantiated claim","safeguard judicial impartiality","examine procedural safeguards"],"correctAnswer":"avoid partisan framing","explanation":"«avoid partisan framing» — «избегать партийно-пристрастной подачи»."}],"durationMinutes":10}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
