INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000208,'quizzes','{"id":760200000000208,"title":"A2 · Политика · Гражданская жизнь · Quiz 8","description":"A2: гражданская жизнь. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A2","icon":"📝","xp":25,"category":"Гражданская жизнь","track":"Политика","topic":"Гражданская жизнь","duration":"6 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «elect a leader».","options":["принять решение","государственная услуга","избрать лидера","школьный совет"],"correctAnswer":"избрать лидера","explanation":"«elect a leader» — «избрать лидера»."},{"id":2,"question":"Какое выражение на британском английском соответствует «собрание сообщества»?","options":["community meeting","elect a leader","share an opinion","public discussion"],"correctAnswer":"community meeting","explanation":"«community meeting» — «собрание сообщества»."},{"id":3,"question":"Выбери точное русское значение выражения «school council».","options":["местный совет","государственная услуга","школьный совет","равное обращение"],"correctAnswer":"школьный совет","explanation":"«school council» — «школьный совет»."},{"id":4,"question":"Выбери точное русское значение выражения «share an opinion».","options":["собрание сообщества","государственная услуга","поделиться мнением","равное обращение"],"correctAnswer":"поделиться мнением","explanation":"«share an opinion» — «поделиться мнением»."},{"id":5,"question":"Какое выражение на британском английском соответствует «местный совет»?","options":["local council","equal treatment","citizens'' rights","school council"],"correctAnswer":"local council","explanation":"«local council» — «местный совет»."},{"id":6,"question":"Выбери точное русское значение выражения «citizens'' rights».","options":["местный совет","права граждан","общественная библиотека","государственная услуга"],"correctAnswer":