INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000211,'quizzes','{"id":760200000000211,"title":"C1 · Политика · Гражданская жизнь · Quiz 11","description":"C1: гражданская жизнь. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"📝","xp":43,"category":"Гражданская жизнь","track":"Политика","topic":"Гражданская жизнь","duration":"9 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «democratic legitimacy».","options":["конфликт интересов","делиберативная демократия","институциональные гарантии","демократическая легитимность"],"correctAnswer":"демократическая легитимность","explanation":"«democratic legitimacy» — «демократическая легитимность»."},{"id":2,"question":"Какое выражение на британском английском соответствует «конфликт интересов»?","options":["conflict of interest","judicial independence","public-sector accountability","procedural fairness"],"correctAnswer":"conflict of interest","explanation":"«conflict of interest» — «конфликт интересов»."},{"id":3,"question":"Выбери точное русское значение выражения «institutional safeguards».","options":["независимость судебной власти","институциональные гарантии","парламентский контроль","делиберативная демократия"],"correctAnswer":"институциональные гарантии","explanation":"«institutional safeguards» — «институциональные гарантии»."},{"id":4,"question":"Выбери точное русское значение выражения «constitutional interpretation».","options":["толкование конституции","демократическая легитимность","обсуждение на основе фактических данных","процедурная справедливость"],"correctAnswer":"толкование конституции","explanation":"«constitutional interpretation» — «толкование конституции»."},{"id":5,"question":"Какое выражение на британском английском соответствует «оценка государственной политики»?","options":["procedural fairness","democratic legitimacy","policy evaluation","conflic