INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000212,'quizzes','{"id":760200000000212,"title":"C2 · Политика · Гражданская жизнь · Quiz 12","description":"C2: гражданская жизнь. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"📝","xp":45,"category":"Гражданская жизнь","track":"Политика","topic":"Гражданская жизнь","duration":"10 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «examine procedural safeguards».","options":["оценить легитимность института","сформулировать проверку соразмерности","избегать партийно-пристрастной подачи","изучить процессуальные гарантии"],"correctAnswer":"изучить процессуальные гарантии","explanation":"«examine procedural safeguards» — «изучить процессуальные гарантии»."},{"id":2,"question":"Какое выражение на британском английском соответствует «оспорить неподкреплённое утверждение»?","options":["articulate a proportionality test","reconcile competing public interests","challenge an unsubstantiated claim","examine procedural safeguards"],"correctAnswer":"challenge an unsubstantiated claim","explanation":"«challenge an unsubstantiated claim» — «оспорить неподкреплённое утверждение»."},{"id":3,"question":"Выбери точное русское значение выражения «assess democratic resilience».","options":["проанализировать захват регулятора","оценить устойчивость демократии","оспорить неподкреплённое утверждение","сбалансировать прозрачность и конфиденциальность"],"correctAnswer":"оценить устойчивость демократии","explanation":"«assess democratic resilience» — «оценить устойчивость демократии»."},{"id":4,"question":"Выбери точное русское значение выражения «safeguard judicial impartiality».","options":["сбалансировать прозрачность и конфиденциальность","оценить устойчивость демократии","изучить процессуальные гарантии","обеспечить беспристрастность суда"],"correctAnswer":"обеспечить беспристрастность суда","explanation":"«safeguard judicial impartiality» — «обеспечить беспристрастность суда»."},{"id":5,"question":"Какое выражение на британском английском соответствует «сбалансировать прозрачность и конфиденциальность»?","options":["distinguish correlation from causation","challenge an unsubstantiated claim","balance transparency and privacy","reconcile competing public interests"],"correctAnswer":"balance transparency and privacy","explanation":"«balance transparency and privacy» — «сбалансировать прозрачность и конфиденциальность»."},{"id":6,"question":"Выбери точное русское значение выражения «avoid partisan framing».","options":["избегать партийно-пристрастной подачи","оценить устойчивость демократии","тщательно изучить конституционные ограничения","сформулировать проверку соразмерности"],"correctAnswer":"избегать партийно-пристрастной подачи","explanation":"«avoid partisan framing» — «избегать партийно-пристрастной подачи»."},{"id":7,"question":"Выбери точное русское значение выражения «evaluate institutional legitimacy».","options":["изучить процессуальные гарантии","обеспечить беспристрастность суда","отличить корреляцию от причинности","оценить легитимность института"],"correctAnswer":"оценить легитимность института","explanation":"«evaluate institutional legitimacy» — «оценить легитимность института»."},{"id":8,"question":"Какое выражение на британском английском соответствует «отличить корреляцию от причинности»?","options":["avoid partisan framing","examine procedural safeguards","distinguish correlation from causation","balance transparency and privacy"],"correctAnswer":"distinguish correlation from causation","explanation":"«distinguish correlation from causation» — «отличить корреляцию от причинности»."}],"durationMinutes":10}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
