INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000222,'quizzes','{"id":760200000000222,"title":"B2 · Политика · Институты и решения · Quiz 22","description":"B2: институты и решения. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"📝","xp":35,"category":"Институты и решения","track":"Политика","topic":"Институты и решения","duration":"8 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «public consultation».","options":["участие в выборах","общественные консультации","реализация государственной политики","конституционные права"],"correctAnswer":"общественные консультации","explanation":"«public consultation» — «общественные консультации»."},{"id":2,"question":"Какое выражение на британском английском соответствует «представительство меньшинств»?","options":["legislative proposal","constitutional rights","minority representation","policy implementation"],"correctAnswer":"minority representation","explanation":"«minority representation» — «представительство меньшинств»."},{"id":3,"question":"Выбери точное русское значение выражения «constitutional rights».","options":["реализация государственной политики","конституционные права","политика на основе фактических данных","политическая подотчётность"],"correctAnswer":"конституционные права","explanation":"«constitutional rights» — «конституционные права»."},{"id":4,"question":"Выбери точное русское значение выражения «institutional transparency».","options":["политическая подотчётность","прозрачность институтов","медиаграмотность","представительство меньшинств"],"correctAnswer":"прозрачность институтов","explanation":"«institutional transparency» — «прозрачность институтов»."},{"id":5,"question":"Какое выражение на британском английском соответствует «медиаграмотность»?","options":["minority representation","media literacy","independent oversight","public consultation"],"c