INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000223,'quizzes','{"id":760200000000223,"title":"C1 · Политика · Институты и решения · Quiz 23","description":"C1: институты и решения. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"📝","xp":40,"category":"Институты и решения","track":"Политика","topic":"Институты и решения","duration":"9 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «conflict of interest».","options":["оценка государственной политики","парламентский контроль","конфликт интересов","делиберативная демократия"],"correctAnswer":"конфликт интересов","explanation":"«conflict of interest» — «конфликт интересов»."},{"id":2,"question":"Какое выражение на британском английском соответствует «толкование конституции»?","options":["policy evaluation","constitutional interpretation","institutional safeguards","procedural fairness"],"correctAnswer":"constitutional interpretation","explanation":"«constitutional interpretation» — «толкование конституции»."},{"id":3,"question":"Выбери точное русское значение выражения «procedural fairness».","options":["независимость судебной власти","конфликт интересов","подотчётность государственного сектора","процедурная справедливость"],"correctAnswer":"процедурная справедливость","explanation":"«procedural fairness» — «процедурная справедливость»."},{"id":4,"question":"Выбери точное русское значение выражения «policy evaluation».","options":["институциональные гарантии","процедурная справедливость","оценка государственной политики","гражданская вовлечённость"],"correctAnswer":"оценка государственной политики","explanation":"«policy evaluation» — «оценка государственной политики»."},{"id":5,"question":"Какое выражение на британском английском соответствует «институциональные гарантии»?","options":["parliamentary scrutiny","evidence-based deliberation","conflict of interest","institutional safeguards"],"correctAnswer":"institutional safeguards","explanation":"«institutional safeguards» — «институциональные гарантии»."},{"id":6,"question":"Выбери точное русское значение выражения «parliamentary scrutiny».","options":["делиберативная демократия","парламентский контроль","демократическая легитимность","независимость судебной власти"],"correctAnswer":"парламентский контроль","explanation":"«parliamentary scrutiny» — «парламентский контроль»."},{"id":7,"question":"Выбери точное русское значение выражения «deliberative democracy».","options":["парламентский контроль","обсуждение на основе фактических данных","делиберативная демократия","институциональные гарантии"],"correctAnswer":"делиберативная демократия","explanation":"«deliberative democracy» — «делиберативная демократия»."},{"id":8,"question":"Какое выражение на британском английском соответствует «гражданская вовлечённость»?","options":["institutional safeguards","procedural fairness","civic engagement","conflict of interest"],"correctAnswer":"civic engagement","explanation":"«civic engagement» — «гражданская вовлечённость»."}],"durationMinutes":9}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000224,'quizzes','{"id":760200000000224,"title":"C2 · Политика · Институты и решения · Quiz 24","description":"C2: институты и решения. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"📝","xp":45,"category":"Институты и решения","track":"Политика","topic":"Институты и решения","duration":"10 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «evaluate institutional legitimacy».","options":["оспорить неподкреплённое утверждение","оценить легитимность института","сформулировать проверку соразмерности","проанализировать захват регулятора"],"correctAnswer":"оценить легитимность института","explanation":"«evaluate institutional legitimacy» — «оценить легитимность института»."},{"id":2,"question":"Какое выражение на британском английском соответствует «изучить процессуальные гарантии»?","options":["articulate a proportionality test","challenge an unsubstantiated claim","analyse regulatory capture","examine procedural safeguards"],"correctAnswer":"examine procedural safeguards","explanation":"«examine procedural safeguards» — «изучить процессуальные гарантии»."},{"id":3,"question":"Выбери точное русское значение выражения «scrutinise constitutional constraints».","options":["избегать партийно-пристрастной подачи","оценить устойчивость демократии","тщательно изучить конституционные ограничения","согласовать конкурирующие общественные интересы"],"correctAnswer":"тщательно изучить конституционные ограничения","explanation":"«scrutinise constitutional constraints» — «тщательно изучить конституционные ограничения»."},{"id":4,"question":"Выбери точное русское значение выражения «balance transparency and privacy».","options":["избегать партийно-пристрастной подачи","тщательно изучить конституционные ограничения","отличить корреляцию от причинности","сбалансировать прозрачность и конфиденциальность"],"correctAnswer":"сбалансировать прозрачность и конфиденциальность","explanation":"«balance transparency and privacy» — «сбалансировать прозрачность и конфиденциальность»."},{"id":5,"question":"Какое выражение на британском английском соответствует «проанализировать захват регулятора»?","options":["safeguard judicial impartiality","distinguish correlation from causation","analyse regulatory capture","examine procedural safeguards"],"correctAnswer":"analyse regulatory capture","explanation":"«analyse regulatory capture» — «проанализировать захват регулятора»."},{"id":6,"question":"Выбери точное русское значение выражения «distinguish correlation from causation».","options":["оценить устойчивость демократии","оспорить неподкреплённое утверждение","обеспечить беспристрастность суда","отличить корреляцию от причинности"],"correctAnswer":"отличить корреляцию от причинности","explanation":"«distinguish correlation from causation» — «отличить корреляцию от причинности»."},{"id":7,"question":"Выбери точное русское значение выражения «safeguard judicial impartiality».","options":["оспорить неподкреплённое утверждение","обеспечить беспристрастность суда","проанализировать захват регулятора","тщательно изучить конституционные ограничения"],"correctAnswer":"обеспечить беспристрастность суда","explanation":"«safeguard judicial impartiality» — «обеспечить беспристрастность суда»."},{"id":8,"question":"Какое выражение на британском английском соответствует «сформулировать проверку соразмерности»?","options":["assess democratic resilience","articulate a proportionality test","safeguard judicial impartiality","challenge an unsubstantiated claim"],"correctAnswer":"articulate a proportionality test","explanation":"«articulate a proportionality test» — «сформулировать проверку соразмерности»."}],"durationMinutes":10}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
