INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000227,'quizzes','{"id":760200000000227,"title":"B1 · Политика · Аргументы и источники · Quiz 27","description":"B1: аргументы и источники. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"📝","xp":30,"category":"Аргументы и источники","track":"Политика","topic":"Аргументы и источники","duration":"7 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «public debate».","options":["гражданское участие","государственная политика","общественные дебаты","местные выборы"],"correctAnswer":"общественные дебаты","explanation":"«public debate» — «общественные дебаты»."},{"id":2,"question":"Какое выражение на британском английском соответствует «независимая журналистика»?","options":["independent journalism","public interest","civic participation","government funding"],"correctAnswer":"independent journalism","explanation":"«independent journalism» — «независимая журналистика»."},{"id":3,"question":"Выбери точное русское значение выражения «local election».","options":["государственное финансирование","местные выборы","представительная демократия","надёжный источник"],"correctAnswer":"местные выборы","explanation":"«local election» — «местные выборы»."},{"id":4,"question":"Выбери точное русское значение выражения «social responsibility».","options":["независимая журналистика","общественный интерес","общественная ответственность","мирное выражение несогласия"],"correctAnswer":"общественная ответственность","explanation":"«social responsibility» — «общественная ответственность»."},{"id":5,"question":"Какое выражение на британском английском соответствует «надёжный источник»?","options":["public interest","reliable source","voting system","representative democracy"],"correctAnswer":"reliable source","explanation":"«reliable source» — «надёжный источник»."},{"id":6,"question":"Выбери точное русское значение выражения «representative democracy».","options":["представительная демократия","общественная ответственность","независимая журналистика","система голосования"],"correctAnswer":"представительная демократия","explanation":"«representative democracy» — «представительная демократия»."},{"id":7,"question":"Выбери точное русское значение выражения «voting system».","options":["независимая журналистика","государственная политика","система голосования","общественный интерес"],"correctAnswer":"система голосования","explanation":"«voting system» — «система голосования»."},{"id":8,"question":"Какое выражение на британском английском соответствует «мирное выражение несогласия»?","options":["public interest","peaceful disagreement","independent journalism","representative democracy"],"correctAnswer":"peaceful disagreement","explanation":"«peaceful disagreement» — «мирное выражение несогласия»."}],"durationMinutes":7}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000228,'quizzes','{"id":760200000000228,"title":"B2 · Политика · Аргументы и источники · Quiz 28","description":"B2: аргументы и источники. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"📝","xp":35,"category":"Аргументы и источники","track":"Политика","topic":"Аргументы и источники","duration":"8 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «independent oversight».","options":["политика на основе фактических данных","независимый надзор","реализация государственной политики","конституционные права"],"correctAnswer":"независимый надзор","explanation":"«independent oversight» — «независимый надзор»."},{"id":2,"question":"Какое выражение на британском английском соответствует «политическая подотчётность»?","options":["constitutional rights","independent oversight","minority representation","political accountability"],"correctAnswer":"political accountability","explanation":"«political accountability» — «политическая подотчётность»."},{"id":3,"question":"Выбери точное русское значение выражения «constitutional rights».","options":["реализация государственной политики","медиаграмотность","независимый надзор","конституционные права"],"correctAnswer":"конституционные права","explanation":"«constitutional rights» — «конституционные права»."},{"id":4,"question":"Выбери точное русское значение выражения «minority representation».","options":["представительство меньшинств","прозрачность институтов","медиаграмотность","общественные консультации"],"correctAnswer":"представительство меньшинств","explanation":"«minority representation» — «представительство меньшинств»."},{"id":5,"question":"Какое выражение на британском английском соответствует «участие в выборах»?","options":["electoral participation","legislative proposal","parliamentary committee","minority representation"],"correctAnswer":"electoral participation","explanation":"«electoral participation» — «участие в выборах»."},{"id":6,"question":"Выбери точное русское значение выражения «policy implementation».","options":["независимый надзор","представительство меньшинств","реализация государственной политики","общественные консультации"],"correctAnswer":"реализация государственной политики","explanation":"«policy implementation» — «реализация государственной политики»."},{"id":7,"question":"Выбери точное русское значение выражения «institutional transparency».","options":["медиаграмотность","участие в выборах","прозрачность институтов","общественные консультации"],"correctAnswer":"прозрачность институтов","explanation":"«institutional transparency» — «прозрачность институтов»."},{"id":8,"question":"Какое выражение на британском английском соответствует «медиаграмотность»?","options":["evidence-based policy","constitutional rights","parliamentary committee","media literacy"],"correctAnswer":"media literacy","explanation":"«media literacy» — «медиаграмотность»."}],"durationMinutes":8}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000229,'quizzes','{"id":760200000000229,"title":"C1 · Политика · Аргументы и источники · Quiz 29","description":"C1: аргументы и источники. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"📝","xp":40,"category":"Аргументы и источники","track":"Политика","topic":"Аргументы и источники","duration":"9 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «deliberative democracy».","options":["независимость судебной власти","институциональные гарантии","конфликт интересов","делиберативная демократия"],"correctAnswer":"делиберативная демократия","explanation":"«deliberative democracy» — «делиберативная демократия»."},{"id":2,"question":"Какое выражение на британском английском соответствует «гражданская вовлечённость»?","options":["judicial independence","public-sector accountability","civic engagement","democratic legitimacy"],"correctAnswer":"civic engagement","explanation":"«civic engagement» — «гражданская вовлечённость»."},{"id":3,"question":"Выбери точное русское значение выражения «procedural fairness».","options":["оценка государственной политики","процедурная справедливость","конфликт интересов","делиберативная демократия"],"correctAnswer":"процедурная справедливость","explanation":"«procedural fairness» — «процедурная справедливость»."},{"id":4,"question":"Выбери точное русское значение выражения «policy evaluation».","options":["толкование конституции","демократическая легитимность","конфликт интересов","оценка государственной политики"],"correctAnswer":"оценка государственной политики","explanation":"«policy evaluation» — «оценка государственной политики»."},{"id":5,"question":"Какое выражение на британском английском соответствует «парламентский контроль»?","options":["conflict of interest","constitutional interpretation","evidence-based deliberation","parliamentary scrutiny"],"correctAnswer":"parliamentary scrutiny","explanation":"«parliamentary scrutiny» — «парламентский контроль»."},{"id":6,"question":"Выбери точное русское значение выражения «public-sector accountability».","options":["конфликт интересов","подотчётность государственного сектора","гражданская вовлечённость","толкование конституции"],"correctAnswer":"подотчётность государственного сектора","explanation":"«public-sector accountability» — «подотчётность государственного сектора»."},{"id":7,"question":"Выбери точное русское значение выражения «constitutional interpretation».","options":["обсуждение на основе фактических данных","делиберативная демократия","толкование конституции","демократическая легитимность"],"correctAnswer":"толкование конституции","explanation":"«constitutional interpretation» — «толкование конституции»."},{"id":8,"question":"Какое выражение на британском английском соответствует «независимость судебной власти»?","options":["constitutional interpretation","judicial independence","democratic legitimacy","public-sector accountability"],"correctAnswer":"judicial independence","explanation":"«judicial independence» — «независимость судебной власти»."}],"durationMinutes":9}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000230,'quizzes','{"id":760200000000230,"title":"C2 · Политика · Аргументы и источники · Quiz 30","description":"C2: аргументы и источники. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"📝","xp":45,"category":"Аргументы и источники","track":"Политика","topic":"Аргументы и источники","duration":"10 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «articulate a proportionality test».","options":["обеспечить беспристрастность суда","изучить процессуальные гарантии","сформулировать проверку соразмерности","отличить корреляцию от причинности"],"correctAnswer":"сформулировать проверку соразмерности","explanation":"«articulate a proportionality test» — «сформулировать проверку соразмерности»."},{"id":2,"question":"Какое выражение на британском английском соответствует «обеспечить беспристрастность суда»?","options":["balance transparency and privacy","safeguard judicial impartiality","challenge an unsubstantiated claim","avoid partisan framing"],"correctAnswer":"safeguard judicial impartiality","explanation":"«safeguard judicial impartiality» — «обеспечить беспристрастность суда»."},{"id":3,"question":"Выбери точное русское значение выражения «avoid partisan framing».","options":["сформулировать проверку соразмерности","оспорить неподкреплённое утверждение","изучить процессуальные гарантии","избегать партийно-пристрастной подачи"],"correctAnswer":"избегать партийно-пристрастной подачи","explanation":"«avoid partisan framing» — «избегать партийно-пристрастной подачи»."},{"id":4,"question":"Выбери точное русское значение выражения «assess democratic resilience».","options":["оценить легитимность института","избегать партийно-пристрастной подачи","отличить корреляцию от причинности","оценить устойчивость демократии"],"correctAnswer":"оценить устойчивость демократии","explanatio