INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000234,'quizzes','{"id":760200000000234,"title":"B2 · Политика · Общество и правила · Quiz 34","description":"B2: общество и правила. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"📝","xp":35,"category":"Общество и правила","track":"Политика","topic":"Общество и правила","duration":"8 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «constitutional rights».","options":["политическая подотчётность","представительство меньшинств","парламентский комитет","конституционные права"],"correctAnswer":"конституционные права","explanation":"«constitutional rights» — «конституционные права»."},{"id":2,"question":"Какое выражение на британском английском соответствует «реализация государственной политики»?","options":["minority representation","constitutional rights","policy implementation","public consultation"],"correctAnswer":"policy implementation","explanation":"«policy implementation» — «реализация государственной политики»."},{"id":3,"question":"Выбери точное русское значение выражения «minority representation».","options":["парламентский комитет","политика на основе фактических данных","представительство меньшинств","прозрачность институтов"],"correctAnswer":"представительство меньшинств","explanation":"«minority representation» — «представительство меньшинств»."},{"id":4,"question":"Выбери точное русское значение выражения «parliamentary committee».","options":["общественные консультации","законодательное предложение","парламентский комитет","медиаграмотность"],"correctAnswer":"парламентский комитет","explanation":"«parliamentary committee» — «парламентский комитет»."},{"id":5,"question":"Какое выражение на британском английском соответствует «общественные консультации»?","options":["legislative proposal","political accountability","public consultation","evidence-based policy"],"correctAnswer":"public consultation","explanation":"«public consultation» — «общественные консультации»."},{"id":6,"question":"Выбери точное русское значение выражения «electoral participation».","options":["конституционные права","независимый надзор","медиаграмотность","участие в выборах"],"correctAnswer":"участие в выборах","explanation":"«electoral participation» — «участие в выборах»."},{"id":7,"question":"Выбери точное русское значение выражения «legislative proposal».","options":["политическая подотчётность","конституционные права","прозрачность институтов","законодательное предложение"],"correctAnswer":"законодательное предложение","explanation":"«legislative proposal» — «законодательное предложение»."},{"id":8,"question":"Какое выражение на британском английском соответствует «медиаграмотность»?","options":["media literacy","electoral participation","parliamentary committee","constitutional rights"],"correctAnswer":"media literacy","explanation":"«media literacy» — «медиаграмотность»."}],"durationMinutes":8}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000235,'quizzes','{"id":760200000000235,"title":"C1 · Политика · Общество и правила · Quiz 35","description":"C1: общество и правила. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"📝","xp":40,"category":"Общество и правила","track":"Политика","topic":"Общество и правила","duration":"9 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «conflict of interest».","options":["конфликт интересов","обсуждение на основе фактических данных","парламентский контроль","оценка государственной политики"],"correctAnswer":"конфликт интересов","explanation":"«conflict of interest» — «конфликт интересов»."},{"id":2,"question":"Какое выражение на британском английском соответствует «обсуждение на основе фактических данных»?","options":["judicial independence","constitutional interpretation","evidence-based deliberation","civic engagement"],"correctAnswer":"evidence-based deliberation","explanation":"«evidence-based deliberation» — «обсуждение на основе фактических данных»."},{"id":3,"question":"Выбери точное русское значение выражения «public-sector accountability».","options":["подотчётность государственного сектора","процедурная справедливость","парламентский контроль","толкование конституции"],"correctAnswer":"подотчётность государственного сектора","explanation":"«public-sector accountability» — «подотчётность государственного сектора»."},{"id":4,"question":"Выбери точное русское значение выражения «procedural fairness».","options":["институциональные гарантии","делиберативная демократия","подотчётность государственного сектора","процедурная справедливость"],"correctAnswer":"процедурная справедливость","explanation":"«procedural fairness» — «процедурная справедливость»."},{"id":5,"question":"Какое выражение на британском английском соответствует «делиберативная демократия»?","options":["deliberative democracy","civic engagement","evidence-based deliberation","constitutional interpretation"],"correctAnswer":"deliberative democracy","explanation":"«deliberative democracy» — «делиберативная демократия»."},{"id":6,"question":"Выбери точное русское значение выражения «policy evaluation».","options":["подотчётность государственного сектора","толкование конституции","оценка государственной политики","делиберативная демократия"],"correctAnswer":"оценка государственной политики","explanation":"«policy evaluation» — «оценка государственной политики»."},{"id":7,"question":"Выбери точное русское значение выражения «judicial independence».","options":["гражданская вовлечённость","толкование конституции","независимость судебной власти","процедурная справедливость"],"correctAnswer":"независимость судебной власти","explanation":"«judicial independence» — «независимость судебной власти»."},{"id":8,"question":"Какое выражение на британском английском соответствует «демократическая легитимность»?","options":["constitutional interpretation","policy evaluation","democratic legitimacy","judicial independence"],"correctAnswer":"democratic legitimacy","explanation":"«democratic legitimacy» — «демократическая легитимность»."}],"durationMinutes":9}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000236,'quizzes','{"id":760200000000236,"title":"C2 · Политика · Общество и правила · Quiz 36","description":"C2: общество и правила. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"📝","xp":48,"category":"Общество и правила","track":"Политика","topic":"Общество и правила","duration":"10 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «distinguish correlation from causation».","options":["согласовать конкурирующие общественные интересы","сформулировать проверку соразмерности","отличить корреляцию от причинности","изучить процессуальные гарантии"],"correctAnswer":"отличить корреляцию от причинности","explanation":"«distinguish correlation from causation» — «отличить корреляцию от причинности»."},{"id":2,"question":"Какое выражение на британском английском соответствует «оценить устойчивость демократии»?","options":["distinguish correlation from causation","evaluate institutional legitimacy","scrutinise constitutional constraints","assess democratic resilience"],"correctAnswer":"assess democratic resilience","explanation":"«assess democratic resilience» — «оценить устойчивость демократии»."},{"id":3,"question":"Выбери точное русское значение выражения «scrutinise constitutional constraints».","options":["тщательно изучить конституционные ограничения","сбалансировать прозрачность и конфиденциальность","проанализировать захват регулятора","оценить легитимность института"],"correctAnswer":"тщательно изучить конституционные ограничения","explanation":"«scrutinise constitutional constraints» — «тщательно изучить конституционные ограничения»."},{"id":4,"question":"Выбери точное русское значение выражения «challenge an unsubstantiated claim».","options":["оценить устойчивость демократии","оспорить неподкреплённое утверждение","тщательно изучить конституционные ограничения","сформулировать проверку соразмерности"],"correctAnswer":"оспорить неподкреплённое утверждение","explanation":"«challenge an unsubstantiated claim» — «оспорить неподкреплённое утверждение»."},{"id":5,"question":"Какое выражение на британском английском соответствует «сформулировать проверку соразмерности»?","options":["balance transparency and privacy","assess democratic resilience","articulate a proportionality test","evaluate institutional legitimacy"],"correctAnswer":"articulate a proportionality test","explanation":"«articulate a proportionality test» — «сформулировать проверку соразмерности»."},{"id":6,"question":"Выбери точное русское значение выражения «examine procedural safeguards».","options":["изучить процессуальные гарантии","согласовать конкурирующие общественные интересы","оценить легитимность института","проанализировать захват регулятора"],"correctAnswer":"изучить процессуальные гарантии","explanation":"«examine procedural safeguards» — «изучить процессуальные гарантии»."},{"id":7,"question":"Выбери точное русское значение выражения «balance transparency and privacy».","options":["сбалансировать прозрачность и конфиденциальность","отличить корреляцию от причинности","оценить легитимность института","оспорить неподкреплённое утверждение"],"correctAnswer":"сбалансировать прозрачность и конфиденциальность","explanation":"«balance transparency and privacy» — «сбалансировать прозрачность и конфиденциальность»."},{"id":8,"question":"Какое выражение на британском английском соответствует «оценить легитимность института»?","options":["examine procedural safeguards","evaluate institutional legitimacy","reconcile competing public interests","distinguish correlation from causation"],"correctAnswer":"evaluate institutional legitimacy","explanation":"«evaluate institutional legitimacy» — «оценить легитимность института»."}],"durationMinutes":10}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
