lanation":"«public library» — «общественная библиотека»."},{"id":7,"question":"Выбери точное русское значение выражения «public service».","options":["избрать лидера","права граждан","равное обращение","государственная услуга"],"correctAnswer":"государственная услуга","explanation":"«public service» — «государственная услуга»."},{"id":8,"question":"Какое выражение на британском английском соответствует «собрание сообщества»?","options":["local council","public service","community meeting","elect a leader"],"correctAnswer":"community meeting","explanation":"«community meeting» — «собрание сообщества»."}],"durationMinutes":6}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000239,'quizzes','{"id":760200000000239,"title":"B1 · Политика · Гражданская жизнь · Quiz 39","description":"B1: гражданская жизнь. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"📝","xp":30,"category":"Гражданская жизнь","track":"Политика","topic":"Гражданская жизнь","duration":"7 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «peaceful disagreement».","options":["мирное выражение несогласия","общественные дебаты","государственная политика","независимая журналистика"],"correctAnswer":"мирное выражение несогласия","explanation":"«peaceful disagreement» — «мирное выражение несогласия»."},{"id":2,"question":"Какое выражение на британском английском соответствует «независимая журналистика»?","options":["civic participation","public interest","independent journalism","voting system"],"correctAnswer":"independent journalism","explanation":"«independent journalism» — «независимая журналистика»."},{"id":3,"question":"Выбери точное русское значение выражения «representative democracy».","options":["государственное финансирование","местные выборы","представительная демократия","общественные дебаты"],"correctAnswer":"представительная демократия","explanation":"«representative democracy» — «представительная демократия»."},{"id":4,"question":"Выбери точное русское значение выражения «social responsibility».","options":["общественная ответственность","общественные дебаты","независимая журналистика","государственное финансирование"],"correctAnswer":"общественная ответственность","explanation":"«social responsibility» — «общественная ответственность»."},{"id":5,"question":"Какое выражение на британском английском соответствует «надёжный источник»?","options":["public policy","representative democracy","local election","reliable source"],"correctAnswer":"reliable source","explanation":"«reliable source» — «надёжный источник»."},{"id":6,"question":"Выбери точное русское значение выражения «civic participation».","options":["мирное выражение несогласия","система голосования","гражданское участие","общественная ответственность"],"correctAnswer":"гражданское участие","explanation":"«civic participation» — «гражданское участие»."},{"id":7,"question":"Выбери точное русское значение выражения «public policy».","options":["независимая журналистика","мирное выражение несогласия","надёжный источник","государственная политика"],"correctAnswer":"государственная политика","explanation":"«public policy» — «государственная политика»."},{"id":8,"question":"Какое выражение на британском английском соответствует «местные выборы»?","options":["voting system","local election","government funding","peaceful disagreement"],"correctAnswer":"local election","explanation":"«local election» — «местные выборы»."}],"durationMinutes":7}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000240,'quizzes','{"id":760200000000240,"title":"B2 · Политика · Гражданская жизнь · Quiz 40","description":"B2: гражданская жизнь. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"📝","xp":35,"category":"Гражданская жизнь","track":"Политика","topic":"Гражданская жизнь","duration":"8 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «policy implementation».","options":["независимый надзор","конституционные права","прозрачность институтов","реализация государственной политики"],"correctAnswer":"реализация государственной политики","explanation":"«policy implementation» — «реализация государственной политики»."},{"id":2,"question":"Какое выражение на британском английском соответствует «медиаграмотность»?","options":["electoral participation","policy implementation","media literacy","political accountability"],"correctAnswer":"media literacy","explanation":"«media literacy» — «медиаграмотность»."},{"id":3,"question":"Выбери точное русское значение выражения «electoral participation».","options":["медиаграмотность","участие в выборах","прозрачность институтов","реализация государственной политики"],"correctAnswer":"участие в выборах","explanation":"«electoral participation» — «участие в выборах»."},{"id":4,"question":"Выбери точное русское значение выражения «minority representation».","options":["реализация государственной политики","представительство меньшинств","политика на основе фактических данных","законодательное предложение"],"correctAnswer":"представительство меньшинств","explanation":"«minority representation» — «представительство меньшинств»."},{"id":5,"question":"Какое выражение на британском английском соответствует «парламентский комитет»?","options":["policy implementation","parliamentary committee","constitutional rights","minority representation"],"correctAn