INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000241,'quizzes','{"id":760200000000241,"title":"C1 · Политика · Гражданская жизнь · Quiz 41","description":"C1: гражданская жизнь. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"📝","xp":43,"category":"Гражданская жизнь","track":"Политика","topic":"Гражданская жизнь","duration":"9 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «deliberative democracy».","options":["оценка государственной политики","демократическая легитимность","гражданская вовлечённость","делиберативная демократия"],"correctAnswer":"делиберативная демократия","explanation":"«deliberative democracy» — «делиберативная демократия»."},{"id":2,"question":"Какое выражение на британском английском соответствует «обсуждение на основе фактических данных»?","options":["constitutional interpretation","democratic legitimacy","evidence-based deliberation","policy evaluation"],"correctAnswer":"evidence-based deliberation","explanation":"«evidence-based deliberation» — «обсуждение на основе фактических данных»."},{"id":3,"question":"Выбери точное русское значение выражения «public-sector accountability».","options":["конфликт интересов","обсуждение на основе фактических данных","независимость судебной власти","подотчётность государственного сектора"],"correctAnswer":"подотчётность государственного сектора","explanation":"«public-sector accountability» — «подотчётность государственного сектора»."},{"id":4,"question":"Выбери точное русское значение выражения «parliamentary scrutiny».","options":["оценка государственной политики","обсуждение на основе фактических данных","делиберативная демократия","парламентский контроль"],"correctAnswer":"парламентский контроль","explanation":"«parliamentary scrutiny» — «парламентский контроль»."},{"id":5,"question":"Какое выражение на британском английском соответствует «гражданс