INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000242,'quizzes','{"id":760200000000242,"title":"C2 · Политика · Гражданская жизнь · Quiz 42","description":"C2: гражданская жизнь. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"📝","xp":45,"category":"Гражданская жизнь","track":"Политика","topic":"Гражданская жизнь","duration":"10 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «distinguish correlation from causation».","options":["отличить корреляцию от причинности","оценить устойчивость демократии","изучить процессуальные гарантии","сбалансировать прозрачность и конфиденциальность"],"correctAnswer":"отличить корреляцию от причинности","explanation":"«distinguish correlation from causation» — «отличить корреляцию от причинности»."},{"id":2,"question":"Какое выражение на британском английском соответствует «изучить процессуальные гарантии»?","options":["reconcile competing public interests","examine procedural safeguards","scrutinise constitutional constraints","challenge an unsubstantiated claim"],"correctAnswer":"examine procedural safeguards","explanation":"«examine procedural safeguards» — «изучить процессуальные гарантии»."},{"id":3,"question":"Выбери точное русское значение выражения «challenge an unsubstantiated claim».","options":["сбалансировать прозрачность и конфиденциальность","оспорить неподкреплённое утверждение","обеспечить беспристрастность суда","избегать партийно-пристрастной подачи"],"correctAnswer":"оспорить неподкреплённое утверждение","explanation":"«challenge an unsubstantiated claim» — «оспорить неподкреплённое утверждение»."},{"id":4,"question":"Выбери точное русское значение выражения «articulate a proportionality test».","options":["сформулировать проверку соразмерности","согласовать конкурирующие общественные интересы","отличить корреляцию от причинности","изучить процессуальные гарантии"],"correctAnswer":"сформулировать проверку соразмерности","explanation":"«articulate a proportionality test» — «сформулировать проверку соразмерности»."},{"id":5,"question":"Какое выражение на британском английском соответствует «избегать партийно-пристрастной подачи»?","options":["balance transparency and privacy","safeguard judicial impartiality","reconcile competing public interests","avoid partisan framing"],"correctAnswer":"avoid partisan framing","explanation":"«avoid partisan framing» — «избегать партийно-пристрастной подачи»."},{"id":6,"question":"Выбери точное русское значение выражения «evaluate institutional legitimacy».","options":["сформулировать проверку соразмерности","изучить процессуальные гарантии","оценить легитимность института","тщательно изучить конституционные ограничения"],"correctAnswer":"оценить легитимность института","explanation":"«evaluate institutional legitimacy» — «оценить легитимность института»."},{"id":7,"question":"Выбери точное русское значение выражения «reconcile competing public interests».","options":["оценить устойчивость демократии","согласовать конкурирующие общественные интересы","оспорить неподкреплённое утверждение","обеспечить беспристрастность суда"],"correctAnswer":"согласовать конкурирующие общественные интересы","explanation":"«reconcile competing public interests» — «согласовать конкурирующие общественные интересы»."},{"id":8,"question":"Какое выражение на британском английском соответствует «тщательно изучить конституционные ограничения»?","options":["scrutinise constitutional constraints","avoid partisan framing","safeguard judicial impartiality","assess democratic resilience"],"correctAnswer":"scrutinise constitutional constraints","explanation":"«scrutinise constitutional constraints» — «тщательно изучить конституционные ограничения»."}],"durationMinutes":10}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
