INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000245,'quizzes','{"id":760200000000245,"title":"B1 · Политика · Общественные обсуждения · Quiz 45","description":"B1: общественные обсуждения. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"📝","xp":30,"category":"Общественные обсуждения","track":"Политика","topic":"Общественные обсуждения","duration":"7 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «civic participation».","options":["общественный интерес","мирное выражение несогласия","гражданское участие","государственная политика"],"correctAnswer":"гражданское участие","explanation":"«civic participation» — «гражданское участие»."},{"id":2,"question":"Какое выражение на британском английском соответствует «государственная политика»?","options":["local election","representative democracy","public policy","independent journalism"],"correctAnswer":"public policy","explanation":"«public policy» — «государственная политика»."},{"id":3,"question":"Выбери точное русское значение выражения «public debate».","options":["общественный интерес","надёжный источник","общественные дебаты","местные выборы"],"correctAnswer":"общественные дебаты","explanation":"«public debate» — «общественные дебаты»."},{"id":4,"question":"Выбери точное русское значение выражения «voting system».","options":["независимая журналистика","общественная ответственность","система голосования","общественные дебаты"],"correctAnswer":"система голосования","explanation":"«voting system» — «система голосования»."},{"id":5,"question":"Какое выражение на британском английском соответствует «общественный интерес»?","options":["government funding","representative democracy","voting system","public interest"],"correctAnswer":"public interest","explanation":"«public interest» — «общественный интерес»."},{"id":6,"question":"Выбери точное русское значение выражения «social responsibility».","options":["общественная ответственность","общественные дебаты","гражданское участие","система голосования"],"correctAnswer":"общественная ответственность","explanation":"«social responsibility» — «общественная ответственность»."},{"id":7,"question":"Выбери точное русское значение выражения «peaceful disagreement».","options":["общественная ответственность","представительная демократия","государственная политика","мирное выражение несогласия"],"correctAnswer":"мирное выражение несогласия","explanation":"«peaceful disagreement» — «мирное выражение несогласия»."},{"id":8,"question":"Какое выражение на британском английском соответствует «надёжный источник»?","options":["representative democracy","peaceful disagreement","reliable source","independent journalism"],"correctAnswer":"reliable source","explanation":"«reliable source» — «надёжный источник»."}],"durationMinutes":7}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000246,'quizzes','{"id":760200000000246,"title":"B2 · Политика · Общественные обсуждения · Quiz 46","description":"B2: общественные обсуждения. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"📝","xp":38,"category":"Общественные обсуждения","track":"Политика","topic":"Общественные обсуждения","duration":"8 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «independent oversight».","options":["политическая подотчётность","политика на основе фактических данных","парламентский комитет","независимый надзор"],"correctAnswer":"независимый надзор","explanation":"«independent oversight» — «независимый надзор»."},{"id":2,"question":"Какое выражение на британском английском соответствует «реализация государственной политики»?","options":["policy implementation","legislative proposal","public consultation","political accountability"],"correctAnswer":"policy implementation","explanation":"«policy implementation» — «реализация государственной политики»."},{"id":3,"question":"Выбери точное русское значение выражения «parliamentary committee».","options":["законодательное предложение","представительство меньшинств","парламентский комитет","независимый надзор"],"correctAnswer":"парламентский комитет","explanation":"«parliamentary committee» — «парламентский комитет»."},{"id":4,"question":"Выбери точное русское значение выражения «media literacy».","options":["медиаграмотность","общественные консультации","законодательное предложение","политическая подотчётность"],"correctAnswer":"медиаграмотность","explanation":"«media literacy» — «медиаграмотность»."},{"id":5,"question":"Какое выражение на британском английском соответствует «политическая подотчётность»?","options":["legislative proposal","minority representation","political accountability","public consultation"],"correctAnswer":"political accountability","explanation":"«political accountability» — «политическая подотчётность»."},{"id":6,"question":"Выбери точное русское значение выражения «institutional transparency».","options":["медиаграмотность","участие в выборах","общественные консультации","прозрачность институтов"],"correctAnswer":"прозрачность институтов","explanation":"«institutional transparency» — «прозрачность институтов»."},{"id":7,"question":"Выбери точное русское значение выражения «evidence-based policy».","options":["независимый надзор","политика на основе фактических данных","общественные консультации","реализация государственной политики"],"correctAnswer":"политика на основе фактических данных","explanation":"«evidence-based policy» — «политика на основе фактических данных»."},{"id":8,"question":"Какое выражение на британском английском соответствует «конституционные права»?","options":["evidence-based policy","institutional transparency","constitutional rights","minority representation"],"correctAnswer":"constitutional rights","explanation":"«constitutional rights» — «конституционные права»."}],"durationMinutes":8}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000247,'quizzes','{"id":760200000000247,"title":"C1 · Политика · Общественные обсуждения · Quiz 47","description":"C1: общественные обсуждения. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"📝","xp":40,"category":"Общественные обсуждения","track":"Политика","topic":"Общественные обсуждения","duration":"9 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «deliberative democracy».","options":["подотчётность государственного сектора","конфликт интересов","делиберативная демократия","независимость судебной власти"],"correctAnswer":"делиберативная демократия","explanation":"«deliberative democracy» — «делиберативная демократия»."},{"id":2,"question":"Какое выражение на британском английском соответствует «парламентский контроль»?","options":["public-sector accountability","civic engagement","institutional safeguards","parliamentary scrutiny"],"correctAnswer":"parliamentary scrutiny","explanation":"«parliamentary scrutiny» — «парламентский контроль»."},{"id":3,"question":"Выбери точное русское значение выражения «public-sector accountability».","options":["гражданская вовлечённость","подотчётность государственного сектора","независимость судебной власти","делиберативная демократия"],"correctAnswer":"подотчётность государственного сектора","explanation":"«public-sector accountability» — «подотчётность государственного сектора»."},{"id":4,"question":"Выбери точное русское значение выражения «constitutional interpretation».","options":["толкование конституции","обсуждение на основе фактических данных","демократическая легитимность","гражданская вовлечённость"],"correctAnswer":"толкование конституции","explanation":"«constitutional interpretation» — «толкование конституции»."},{"id":5,"question":"Какое выражение на британском английском соответствует «гражданская вовлечённость»?