INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000248,'quizzes','{"id":760200000000248,"title":"C2 · Политика · Общественные обсуждения · Quiz 48","description":"C2: общественные обсуждения. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"📝","xp":45,"category":"Общественные обсуждения","track":"Политика","topic":"Общественные обсуждения","duration":"10 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «analyse regulatory capture».","options":["оценить устойчивость демократии","согласовать конкурирующие общественные интересы","изучить процессуальные гарантии","проанализировать захват регулятора"],"correctAnswer":"проанализировать захват регулятора","explanation":"«analyse regulatory capture» — «проанализировать захват регулятора»."},{"id":2,"question":"Какое выражение на британском английском соответствует «изучить процессуальные гарантии»?","options":["avoid partisan framing","examine procedural safeguards","distinguish correlation from causation","safeguard judicial impartiality"],"correctAnswer":"examine procedural safeguards","explanation":"«examine procedural safeguards» — «изучить процессуальные гарантии»."},{"id":3,"question":"Выбери точное русское значение выражения «reconcile competing public interests».","options":["сформулировать проверку соразмерности","изучить процессуальные гарантии","согласовать конкурирующие общественные интересы","проанализировать захват регулятора"],"correctAnswer":"согласовать конкурирующие общественные интересы","explanation":"«reconcile competing public interests» — «согласовать конкурирующие общественные интересы»."},{"id":4,"question":"Выбери точное русское значение выражения «balance transparency and privacy».","options":["тщательно изучить конституционные ограничения","сбалансировать прозрачность и конфиденциальность","оспорить неподкреплённое утверждение","проанализировать з